/// <summary>
/// CoC extension
/// MPJ_15465_DirectDebitAutomation
/// </summary>
[ExtensionOf(classStr(CustVendPaymProposal))]
final class METCustVendPaymProposal_Extension
{

}

Method.Source:
    /// <summary>
    /// CoC extension
    /// </summary>
    /// <param name = "_custVendTransOpen">_custVendTransOpen</param>
    /// <param name = "_paymDate">_paymDate</param>
    /// <param name = "_paymCurrency">_paymCurrency</param>
    /// <returns>CustVendPaymProposalLine</returns>
    public CustVendPaymProposalLine buildPaymProposalLine(
        CustVendTransOpen   _custVendTransOpen,
        TransDate           _paymDate,
        CurrencyCode        _paymCurrency)
    {
        CustVendPaymProposalLine proposalLine = next buildPaymProposalLine(
            _custVendTransOpen,
            _paymDate,
            _paymCurrency);

        if(this.ledgerJournalType() == LedgerJournalType::CustPayment)
        {
            boolean addLine = true;

            if(!CustTable::find(_custVendTransOpen.AccountNum).BankAccount)
            {
                addLine = false;
            }
            CustVendDisputeStatus disputeStatus = CustDispute::findByCustTrans(_custVendTransOpen.RefRecId).Status;
            if(disputeStatus == CustVendDisputeStatus::Disputed)
            {
                addLine = false;
            }
            if(!addLine)
            {
                proposalLine.AccountNum = ''; // Bypass addition of line
            }
        }        
        return proposalLine;
    }
